/**
 * The character avalanche: the actual Vellum cast (pulled verbatim from the
 * open-source repo's login-background-characters.svg — the same characters
 * vellum.ai piles along its login page) pouring in from the top right,
 * sweeping through the middle of the hero, and pooling along the bottom
 * edge. Pure CSS animation (no JS state), so it renders on the server and
 * never hydrates.
 *
 * Each character is defined ONCE in a hidden <defs> block and stamped per
 * placement with <use> — body paths carry no fill so they inherit the
 * placement's palette color, while the baked-in eyes keep their own. A
 * translate+scale wrapper (computed from each shape's rendered bounding
 * box) centers every character in the same 0–100 box the layout bands
 * expect.
 *
 * Layout is art-directed as three bands of [x%, y%, sizePx] placements;
 * shape, color and rotation are derived deterministically from the band
 * index so the pile is identical on every render (and between deploys).
 */

const COLORS = [
  "#2e8b4a", // cadet green
  "#23793d", // brand green-dark
  "#f2c744", // yellow
  "#e8792e", // orange
  "#e0567c", // pink
  "#9a6bd8", // purple
  "#2fa39a", // teal
];

