type Placement = {
  x: number;
  y: number;
  size: number;
  rot: number;
  shape: number;
  color: string;
  dur: number;
  delay: number;
};

function place(
  band: Array<[number, number, number]>,
  offset: number,
): Placement[] {
  return band.map(([x, y, size], i) => {
    const n = offset + i;
    return {
      x,
      y,
      size,
      rot: ((n * 41) % 36) - 18,
      shape: n % CAST.length,
      color: COLORS[(n * 3 + offset) % COLORS.length],
      dur: 4.5 + ((n * 13) % 30) / 10,
      delay: ((n * 17) % 40) / 10,
    };
  });
}

const PLACEMENTS = [
  ...place(STREAM, 0),
  ...place(SWEEP, 5),
  ...place(POOL_BACK, 11),
  ...place(POOL_MID, 2),
  ...place(POOL_FRONT, 7),
];

const POOL_PLACEMENTS = [
  ...place(POOL_BACK, 11),
  ...place(POOL_MID, 2),
  ...place(POOL_FRONT, 7),
];

export default function CharacterAvalanche() {
  return <Avalanche placements={PLACEMENTS} />;
}

/**
 * Just the pool: the characters piled along the bottom edge, no stream or
 * sweep. The community page floats its welcome bubbles over this pile.
 */
export function CharacterPool() {
  return <Avalanche placements={POOL_PLACEMENTS} />;
}

function Avalanche({ placements }: { placements: Placement[] }) {
  return (
    <div className="avalanche" aria-hidden>
      <svg
        width="0"
        height="0"
        focusable="false"
        aria-hidden
        style={{ position: "absolute" }}
      >
        <defs>
          {CAST.map((Char, i) => (
            <g id={`av-char-${i}`} key={i}>
              <Char />
            </g>
          ))}
        </defs>
      </svg>
      {placements.map((p, i) => (
        <span
          key={i}
          className="av-char"
          style={{
            left: `${p.x}%`,
            top: `${p.y}%`,
            width: p.size,
            transform: `translate(-50%, -50%) rotate(${p.rot}deg)`,
          }}
        >
          <span
            className="av-bob"
            style={{
              animationDuration: `${p.dur}s`,
              animationDelay: `-${p.delay}s`,
            }}
          >
            <svg viewBox="0 0 100 100" width="100%">
              <use href={`#av-char-${p.shape}`} fill={p.color} />
            </svg>
          </span>
        </span>
      ))}
    </div>
  );
}
